function validate(input) {
  const [{ Users = [] }] = input;
  const ids = new Set();
  for (const [id, email] of Users) {
    if (id === null) return 'Every user needs a user_id.';
    if (ids.has(id)) return `user_id ${id} appears twice.`;
    if (email === null) return `User ${id} needs an email.`;
    ids.add(id);
  }
  return null;
}

