function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const from = list => list[pick(list.length)];
  const locals = ['alice', 'bob_99', 'Eve', 'x', '_', '42', 'first.last', 'a-b', 'j+k', '', 'Mia_Lee', 'zoe 1'];
  const domains = ['example', 'mail', 'Domain', 'x', 'mail1', 'my-mail', 'a.b', '', 'web_site', 'leetcode'];
  const endings = ['.com', '.com', '.com', '.net', 'com', '.comm', '.co', '.com.', ''];
  const signs = ['@', '@', '@', '@', '@@', '_at_', ''];
  const count = small ? pick(9) : 1500 + pick(501);
  const ids = [];
  for (let id = 1; id <= (small ? 12 : 4000); id++) ids.push(id);
  for (let i = ids.length - 1; i > 0; i--) { const j = pick(i + 1); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Users = [];
  for (const id of ids.slice(0, count)) {
    // About half the addresses are built only from valid pieces; the rest mix in one or more bad pieces.
    const clean = rand() < 0.5;
    const local = clean ? from(['alice', 'bob_99', 'Eve', 'x', '_', '42', 'Mia_Lee']) : from(locals);
    const domain = clean ? from(['example', 'mail', 'Domain', 'x', 'leetcode']) : from(domains);
    const email = local + (clean ? '@' : from(signs)) + domain + (clean ? '.com' : from(endings));
    Users.push([id, email]);
  }
  return [{ Users }];
}
